+import {createChatOrchestrator} from './chatOrchestrator.js';
+import type {OrchestratorHooks} from './chatOrchestrator.js';
+import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
+import type {AIProvider, MessageChunk} from '../types/ai.js';
+import type {ChatSession} from '../types/session.js';
+
+const promptBuilder = new PromptBuilder({identity: 'Coercion test.'});
+
+const turnSession = (): ChatSession => ({
+  sessionId: 'coercion-session',
+  userId: 'coercion-user',
+  entries: [{role: 'user', content: 'ping', timestamp: '2026-01-01T00:00:00.000Z'}],
+});
+
+const providerThrowing = (thrown: unknown): AIProvider => ({
+  async *sendMessage(): AsyncGenerator<MessageChunk> {
+    const emptyChunks: MessageChunk[] = [];
+    yield* emptyChunks;
+    throw thrown;
+  },
+  generateStructured(): Promise<never> {
+    return Promise.reject(new Error('stub'));
+  },
+});
+
+interface RejectionCapture {
+  threw: boolean;
+  caught: unknown;
+}
+
+const inspectRejection = async (thrown: unknown) => {
+  let hookCalls = 0;
+  let seen: Error | undefined;
+  const hooks: OrchestratorHooks = {
+    onError: async (_session, error) => {
+      hookCalls += 1;
+      seen = error;
+    },
+  };
+
+  const orchestrator = createChatOrchestrator(providerThrowing(thrown), promptBuilder, undefined, {hooks});
+  const outcome = await orchestrator.processMessage(turnSession()).then(
+    (): RejectionCapture => ({threw: false, caught: null}),
+    (caught: unknown): RejectionCapture => ({threw: true, caught})
+  );
+
+  return {
+    hookCalls,
+    receivedError: seen instanceof Error,
+    sameInstance: Object.is(seen, thrown),
+    causeMatches: seen !== undefined && 'cause' in seen ? Object.is(seen.cause, thrown) : false,
+    message: seen ? seen.message : '',
+    rethrowMatches: outcome.threw && Object.is(outcome.caught, thrown),
+  };
+};
+
+describe('ChatOrchestrator onError coercion', () => {
+  it('wraps string, object, and undefined rejections with cause while passing Error instances through', async () => {
+    const wrappedExpectation = (message: string) => ({
+      hookCalls: 1,
+      receivedError: true,
+      sameInstance: false,
+      causeMatches: true,
+      message,
+      rethrowMatches: true,
+    });
+
+    expect({
+      stringCase: await inspectRejection('string boom'),
+      objectCase: await inspectRejection({code: 503, detail: 'upstream down'}),
+      undefinedCase: await inspectRejection(undefined),
+      errorCase: await inspectRejection(new Error('already an error')),
+    }).toEqual({
+      stringCase: wrappedExpectation('string boom'),
+      objectCase: wrappedExpectation("{ code: 503, detail: 'upstream down' }"),
+      undefinedCase: wrappedExpectation('undefined'),
+      errorCase: {
+        hookCalls: 1,
+        receivedError: true,
+        sameInstance: true,
+        causeMatches: false,
+        message: 'already an error',
+        rethrowMatches: true,
+      },
+    });
+  });
+});

